import{_ as a,o as s,c as i,ao as t}from"./chunks/framework.Cg8nWxPv.js";const k=JSON.parse('{"title":"Choose what the globe is textured with","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/basemap.md","filePath":"how-to/basemap.md","lastUpdated":null}'),o={name:"how-to/basemap.md"};function n(h,e,r,l,d,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="Choose-what-the-globe-is-textured-with" tabindex="-1">Choose what the globe is textured with <a class="header-anchor" href="#Choose-what-the-globe-is-textured-with" aria-label="Permalink to &quot;Choose what the globe is textured with {#Choose-what-the-globe-is-textured-with}&quot;">​</a></h1><p>The globe wears the viewer&#39;s bundled Earth texture unless you say otherwise. <code>imagery</code> takes a URL, a directory of tiles on disk, an <a href="/CesiumLink.jl/previews/PR31/reference/server#CesiumLink.Imagery"><code>Imagery</code></a> for the rest, or <code>:none</code>. The server declares it once, and it holds for the session.</p><h2 id="1.-Point-at-a-basemap-on-the-web" tabindex="-1">1. Point at a basemap on the web <a class="header-anchor" href="#1.-Point-at-a-basemap-on-the-web" aria-label="Permalink to &quot;1. Point at a basemap on the web {#1.-Point-at-a-basemap-on-the-web}&quot;">​</a></h2><p>Give the URL template of a tile pyramid. <code>{z}</code>, <code>{x}</code> and <code>{y}</code> are the level, the column and the row:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">start_server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; imagery </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://host/tiles/{z}/{x}/{y}.png&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Nothing is fetched here. The server declares the template as it stands, and the browser asks for the tiles.</p><p><code>tiling</code> is the projection the pyramid is cut in. Leave it alone for a basemap published on the web: <code>{z}/{x}/{y}</code> means Web Mercator, the default. Set it for a pyramid cut the other way:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">start_server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; imagery </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Imagery</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(url; tiling </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :geographic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p>A basemap in the wrong projection still draws. It is stretched towards the poles and the coordinates you send land on the wrong part of it, so check the shape of a coastline before you trust a pin.</p><h2 id="2.-Tile-your-own-raster-and-point-at-it" tabindex="-1">2. Tile your own raster and point at it <a class="header-anchor" href="#2.-Tile-your-own-raster-and-point-at-it" aria-label="Permalink to &quot;2. Tile your own raster and point at it {#2.-Tile-your-own-raster-and-point-at-it}&quot;">​</a></h2><p>Cut the raster into a pyramid with <code>gdal2tiles.py</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdal2tiles.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --zoom=0-7</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> moon.tif</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> moon_tiles/</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # a TMS pyramid</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdal2tiles.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --zoom=0-7</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --xyz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> moon.tif</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> moon_tiles/</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # an XYZ pyramid</span></span></code></pre></div><p>Then name the directory:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">start_server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; imagery </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/data/moon_tiles&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The server mounts it under <code>assets/imagery/</code> and declares that relative URL, so the page fetches the tiles from its own origin and no CORS header is needed.</p><p>State nothing else. The server reads the directory once, at <code>start_server</code>:</p><ul><li><p><strong>The layout.</strong> A <code>tilemapresource.xml</code> in the directory makes it TMS. A numeric level directory and no such file makes it XYZ. gdal2tiles writes TMS by default and XYZ under <code>--xyz</code>.</p></li><li><p><strong>The depth.</strong> For an XYZ directory, the largest numeric level name is the deepest level.</p></li><li><p><strong>The tiling scheme and the depth</strong>, for TMS. <code>tilemapresource.xml</code> carries both, and Cesium reads them out of it. So a <code>tiling = :geographic</code> given with a TMS directory warns and is dropped, and a <code>max_level</code> given with one is dropped without a word.</p></li></ul><p>A directory that holds neither a <code>tilemapresource.xml</code> nor a numeric level directory throws, and the message names both layouts.</p><h2 id="3.-Draw-no-basemap-at-all" tabindex="-1">3. Draw no basemap at all <a class="header-anchor" href="#3.-Draw-no-basemap-at-all" aria-label="Permalink to &quot;3. Draw no basemap at all {#3.-Draw-no-basemap-at-all}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">start_server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; imagery </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :none</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The globe is one flat colour and there is no base layer under it. Use it for a body you have no basemap for, and for a data-only globe where coastlines would read as meaning.</p><h2 id="4.-Put-satellites-around-the-Moon" tabindex="-1">4. Put satellites around the Moon <a class="header-anchor" href="#4.-Put-satellites-around-the-Moon" aria-label="Permalink to &quot;4. Put satellites around the Moon {#4.-Put-satellites-around-the-Moon}&quot;">​</a></h2><p>Declare the shape and the surface together:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CesiumLink</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">moon </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://cartocdn-gusc.global.ssl.fastly.net/opmbuilder/api/v1/map/named/opm-moon-basemap-v0-1/all/{z}/{x}/{y}.png&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> start_server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; ellipsoid </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Ellipsoids</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MOON,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                      imagery </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Imagery</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(moon; max_level </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                                        credit </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;OpenPlanetary Moon basemap · LOLA/USGS&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p><a href="/CesiumLink.jl/previews/PR31/reference/geodesy#CesiumLink.Ellipsoids"><code>Ellipsoids</code></a> names <code>WGS84</code>, <code>MOON</code> and <code>MARS</code>. Any other body is two positive radii: <code>ellipsoid = (a = 2439700.0, b = 2439700.0)</code> draws Mercury.</p><p>Everything you push after this is drawn on that shape. <a href="./coordinates">Work in map coordinates</a> covers what <code>ecef</code> does with the declared ellipsoid.</p><h3 id="The-same-globe,-live" tabindex="-1">The same globe, live <a class="header-anchor" href="#The-same-globe,-live" aria-label="Permalink to &quot;The same globe, live {#The-same-globe,-live}&quot;">​</a></h3><p>The scene below is that Moon basemap over <code>Ellipsoids.MOON</code>, with no Julia process behind it. The page carries the basemap, the shape and the credit in its own address: <code>?imagery=</code>, <code>?ellipsoid=</code> and <code>?credit=</code>. Drag to turn it and scroll to zoom in. Deeper tiles arrive as you go.</p><iframe src="../viewer/index.html?imagery=https://cartocdn-gusc.global.ssl.fastly.net/opmbuilder/api/v1/map/named/opm-moon-basemap-v0-1/all/%7Bz%7D/%7Bx%7D/%7By%7D.png&amp;maxlevel=8&amp;credit=OpenPlanetary%20Moon%20basemap%20%C2%B7%20LOLA%2FUSGS&amp;ellipsoid=1737400,1737400" title="An interactive Moon globe, textured with the OpenPlanetary Moon basemap" loading="lazy" style="width:100%;aspect-ratio:16/10;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><p>The globe&#39;s own credit is plain text, so the link belongs here: the Moon basemap is <a href="https://www.openplanetary.org/" target="_blank" rel="noreferrer">OpenPlanetary</a>, from LOLA/USGS data.</p><p><code>?imagery=</code> reads the layout off the URL: a <code>{z}</code> in it means an XYZ template, and anything else means a TMS pyramid. A server that declares a basemap wins, so these parameters build the globe only where no declaration does.</p><h2 id="5.-Light-the-globe-and-put-a-sky-behind-it" tabindex="-1">5. Light the globe and put a sky behind it <a class="header-anchor" href="#5.-Light-the-globe-and-put-a-sky-behind-it" aria-label="Permalink to &quot;5. Light the globe and put a sky behind it {#5.-Light-the-globe-and-put-a-sky-behind-it}&quot;">​</a></h2><p>Two more keywords change what the globe looks like. Neither touches the basemap:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">start_server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; lighting </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, stars </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><code>lighting</code> lights the globe from the sun at the clock&#39;s time, so a terminator runs across it and the night side goes dark. <code>stars</code> draws the star field, the sun and the moon around it, at that same time. Both are off by default. The <a href="./../examples/satellites">Satellites</a> example turns both on.</p><p>Four conditions to know:</p><ul><li><p><strong>Leave <code>lighting</code> off for a scene whose colours carry its data.</strong> A shaded globe dims a value by where it sits rather than by what it says.</p></li><li><p><strong>The sun stands where the clock says.</strong> Give your windows a real <code>start_time</code>, or the viewer picks a synthetic epoch and the terminator lands somewhere arbitrary — see <a href="/CesiumLink.jl/previews/PR31/reference/windows#CesiumLink.push_window"><code>push_window</code></a>.</p></li><li><p><strong>A star field needs Earth.</strong> The field is Cesium&#39;s own, and Cesium draws it on a WGS84 globe only. A session on another body gets black whatever <code>stars</code> says.</p></li><li><p><strong>Lighting needs Earth as well.</strong> Cesium computes the sun&#39;s direction from Earth&#39;s position and expresses it in Earth&#39;s rotating frame, whatever ellipsoid the session declares. On another body the terminator is Earth&#39;s, in both where it falls and how fast it sweeps. Leave <code>lighting</code> off there.</p></li></ul><h2 id="Two-things-that-bite" tabindex="-1">Two things that bite <a class="header-anchor" href="#Two-things-that-bite" aria-label="Permalink to &quot;Two things that bite {#Two-things-that-bite}&quot;">​</a></h2><p><strong>A template with no <code>max_level</code> keeps asking past the end of the pyramid.</strong> The server probes the depth of a directory, and it cannot probe a remote host. So zoom in far enough and the browser requests levels that are not there: one failed request per tile, and the globe stops sharpening without saying why. Give <code>max_level</code> for any URL-backed basemap.</p><p><strong>The credit is yours.</strong> The viewer draws the <code>credit</code> string over the bottom right of the globe, as text and nothing else. It knows nothing about your tiles, where they came from, or what their licence asks of you. Nothing is drawn if you state nothing.</p><h2 id="When-a-basemap-does-not-build" tabindex="-1">When a basemap does not build <a class="header-anchor" href="#When-a-basemap-does-not-build" aria-label="Permalink to &quot;When a basemap does not build {#When-a-basemap-does-not-build}&quot;">​</a></h2><p>A source that will not build gives the bundled Earth texture, one console message naming the URL, and no credit line. So a globe wearing Earth&#39;s coastlines under a Moon scene is explained in the browser console.</p><p>The fallback catches a source that fails to <strong>build</strong>. A TMS pyramid is fetched to be built, so a dead one falls back. A <code>{z}/{x}/{y}</code> template builds without asking for anything, so a dead host behind it gives blank tiles and one console error per tile.</p><h2 id="Next" tabindex="-1">Next <a class="header-anchor" href="#Next" aria-label="Permalink to &quot;Next {#Next}&quot;">​</a></h2><ul><li><p><a href="./../reference/server">The server</a> — <code>start_server</code>, <code>Imagery</code>, and every keyword.</p></li><li><p><a href="./coordinates">Work in map coordinates</a> — degrees in, ECEF metres out, on the declared shape.</p></li><li><p><a href="./record-replay">Record and replay a session</a> — a recording carries neither the shape nor the basemap, so a Moon replay states both again.</p></li></ul>`,45)])])}const g=a(o,[["render",n]]);export{k as __pageData,g as default};
